    @overload
    def conv(a: int) -> int: ...
    @overload
    def conv(a: str) -> str: ...

def conv(a):
    return a


class A:
    if TYPE_CHECKING:
        @overload
        def get(self, k: int) -> int: ...
        @overload
        def get(self, k: str) -> str: ...
    def get(self, k):
        return k


class B:
    @overload
    def put(self, v: int) -> None: ...
    @overload
    def put(self, v: str) -> None: ...


